#!/usr/bin/env python3
"""Supplement the complete forecast with measured new lifecycle cost and adoption allowance."""
import sys,time,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.structured_common import RUN,PUB,CFG,read,write,sha,verify_freeze
from echo_routing.temporal.structured_budget import caps_fit

def main():
    freeze=verify_freeze('head_check_freeze.json');base=read(PUB/'admission.json');assert base['all_caps_fit'];checks=read(PUB/'head_pipeline_checks.json');assert checks['passed'] and checks['formal_optimizer_updates']==0 and checks['new_visual_producer_forwards']==0;cfg=read(CFG);budget=cfg['budget'];rows=[json.loads(s) for s in (RUN/'processes.jsonl').read_text().splitlines()];allowance=sum(r.get('unmeasured_completed_CPU_accounting_allowance_seconds',0) for r in rows);rate=max(r['per_valid_position_seconds_complete_pipeline'] for r in checks['records']);head_seconds=rate*base['workload']['head_training_valid_positions']*1.5;extra=max(0.,head_seconds-base['head_training_seconds_upper']);new_cpu=base['forecast_new_CPU_hours_including_completed_setup_allowance']+(allowance+extra)/3600;new_gpu=base['forecast_new_GPU_hours_including2hreserve'];storage=base['forecast_new_tracked_peak_upper_bytes'];end=base['forecast_end_epoch']+extra;passed=base['all_caps_fit'] and caps_fit(budget,new_gpu,new_cpu,storage,end);result={'all_caps_fit':passed,'original_complete_forecast_sha256':sha(PUB/'admission.json'),'head_pipeline_checks_sha256':sha(PUB/'head_pipeline_checks.json'),'head_check_freeze_git':freeze['git_commit'],'measured_lifecycle_worst_seconds_per_valid_position':rate,'head_training_upper_seconds_with_full_journal_digest_atomic_overhead':max(head_seconds,base['head_training_seconds_upper']),'additional_training_upper_seconds':extra,'completed_unmeasured_CPU_accounting_allowance_seconds':allowance,'allowance_is_not_measured_CPU_usage':True,'forecast_new_GPU_hours_including2hreserve':new_gpu,'forecast_cumulative_GPU_hours_includingreserve':budget['prior_GPUjob_h']+new_gpu,'forecast_new_CPU_receipt_hours_plus_completed_allowances':new_cpu,'forecast_cumulative_CPU_receipt_hours_plus_allowances':budget['prior_summed_measured_CPUreceipt_h']+budget['prior_setup_budget_allowance_h']+new_cpu,'forecast_new_tracked_peak_upper_bytes':storage,'forecast_cumulative_tracked_peak_upper_bytes':budget['prior_tracked_storage_upper_bytes']+storage,'forecast_end_epoch':end,'earlier_deadline_epoch':min(budget['new_deadline'],budget['cumulative_deadline']),'all8models48000updates24innerrows_main_and_stress_132paired5000bootstrap_retained':True,'score_or_model_performance_used_for_admission':False,'training_backend':'cpu','epoch':time.time()};write(PUB/'formal_runtime_admission.json',result);print(json.dumps(result),flush=True);assert passed
